cd /home/admin1/projects/webhook-gateway && docker compose exec -T api node <<'JS'
(async()=>{
const crypto=await import("node:crypto");
const pg=await import("pg");
const key=JSON.parse(process.env.INTERNAL_EVENT_API_PROJECT_KEYS_JSON||"{}")["server-core"];
if(!key)throw Error("PROJECT_KEY_MISSING");
const rid="req_"+crypto.randomBytes(12).toString("hex");
const event={eventId:rid,eventType:"gace.servercore-bounded-host.requested",sourceId:"server-core-github",destinationId:"server-core-bounded-host",subject:"servercore-bounded-host/project.git_head",time:new Date().toISOString(),data:{schema:"gace.servercore-bounded-host.request/v1",id:rid,command_id:"project.git_head",expected_sha:"7a9ea997f62167946991ecb7734c0859e2d9d57d"}};
const res=await fetch("http://127.0.0.1:7373/internal/events",{method:"POST",headers:{"content-type":"application/json","x-internal-api-token":key},body:JSON.stringify(event)});
console.log("INGRESS",JSON.stringify({request:rid,status:res.status}));
if(res.status!==202)throw Error("INGRESS_NOT_ACCEPTED");
const db=new pg.Client({connectionString:process.env.DATABASE_URL});await db.connect();
let state="UNKNOWN";
for(let i=0;i<12;i++){
const q=await db.query("SELECT d.status,d.last_status_code FROM events e JOIN deliveries d ON d.event_id=e.id WHERE e.source_id=$1 AND e.provider_event_id=$2",["server-core-github",rid]);
state=q.rows[0]?.status||"NOT_YET_VISIBLE";
if(state==="delivered"||state==="dead") {console.log("DELIVERY",JSON.stringify({request:rid,...q.rows[0]}));break;}
await new Promise(r=>setTimeout(r,2000));
}
await db.end();
if(state!=="delivered")throw Error("DELIVERY_NOT_VERIFIED_"+state);
})().catch(e=>{console.log("CHECK_FAILED",e.message);process.exit(2)});
JS
